void compress_string(const char *src, char *dest) {
    const char *run_start = src;
    int count;

    while (*run_start) {
        count = 1;
        while (run_start[count] == run_start[0]) {
            count++;
        }
        *dest++ = *run_start;
        if (count >= 10) {
            *dest++ = (count / 10) + '0';
            *dest++ = (count % 10) + '0';
        } else {
            *dest++ = count + '0';
        }
        run_start += count;
    }
    *dest = '\0';
}

